    const navCount = await page.locator('[id="compose.sketchpad.navbar"]').count().catch(() => -1);
    const rootCount = await page.locator('#root > *').count().catch(() => -1);
    console.log('PROBE', JSON.stringify({ tick:i, inputCount, navCount, rootCount, title: await page.title().catch(() => 'ERR'), closed: page.isClosed() }));
    if (page.isClosed()) break;
  }
  try { await browser.close(); } catch {}
})();
EOF

